async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: Pick<SessionStore, 'listFor'> | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, listOptions(message));
    sendSessionList(ws, summaries.map(toSessionSummaryFrame));
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

function listOptions(message: ListSessionsMessage): SessionListOptions | undefined {
  if (message.limit === undefined && message.before === undefined) return undefined;
  return {
    ...(message.limit !== undefined ? {limit: message.limit} : {}),
    ...(message.before !== undefined ? {before: message.before} : {}),
  };
}

function toSessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

